      "data_requirements": [
        {
          "master_data": "Mixing ratios",
          "content": "Required when a product is produced using different production versions or a mix of external/internal procurement. For procurement type 'X', mixing ratios must be maintained.",
          "transaction_codes": ["CK91N", "CK94", "RB4C_CO_MXR_MGMT (Fiori App)"]
        },
        {
          "master_data": "Costing lot size",
          "content": "Must be maintained in the material master under 'Costing 1'.",
          "transaction_codes": ["MM03"]
        },
        {
          "master_data": "Overhead surcharges and credit objects",
          "content": "Calculated overhead surcharges and credit objects are maintained in the FIORI App.",
          "transaction_codes": ["RB4C_CO_EOS (Fiori App EOS Maintenance or EOS Upload)"]
        }
      ]
    },
    "system_interaction": {
      "mixing_ratios": {
        "steps": [
          "(A1) Access 'Edit Procurement Alternatives' tile in FIORI Launchpad (Product Costing -> Costing Accounting - Section Costing).",
          "(A2) Use 'Create' to add a procurement alternative for the chosen material.",
          "(B1) Access 'Change Mixing Ratios' tile in FIORI Launchpad (Product Costing -> Costing Accounting - Section Costing).",
          "(B2) Insert Material, Plant, Fiscal Year, and Quantity Structure Type 'YX001' to access the maintenance view.",
          "(B3) Maintain mixing ratios between created procurement alternatives.",
          "(C1) Access 'Process Proc.Alt and Mixing Ratios' tile in FIORI Launchpad (Product Costing -> Costing Accounting - Section Costing).",
          "(C2) Use this Fiori App for mass data handling."
        ],
        "additional_info": "More details can be found [here](https://inside-docupedia.bosch.com/confluence/x/0RRN2g)."
