      "costing_lot_size": {
        "steps": [
          "(D1) Access 'Change Material' tile in FIORI Launchpad (Product Costing -> Costing Accounting - Section Material Master).",
          "(D2) Insert Material and Change Number.",
          "(D3) Change the lot size in the 'Costing 1' view."
        ]
      },
      "overhead_surcharges_and_credit_objects": {
        "single_records": {
          "steps": [
            "(E1) Access 'EOS Maintenance' tile in FIORI Launchpad (Product Costing -> Costing Accounting - Section Costing).",
            "(E2) Define filter criteria and press 'Go'.",
            "(E3) Add new surcharges using 'Create', or edit/delete existing entries."
          ]
        },
        "mass_data_upload_download": {
          "steps": [
            "(F1) Access 'EOS Upload' tile in FIORI Launchpad (Product Costing -> Costing Accounting - Section Costing).",
            "(F2) Download surcharge entries by entering filter criteria and pressing 'Go'.",
            "(F3) Upload surcharge entries by selecting a file and pressing 'Upload'.",
            "(F4) Delete surcharge entries if needed."
          ]
        }
      }
    }
  }
}
