        "after": "New layout of invoice form @RB level using ADOBE forms for more flexibility and standardized formats."
      },
      {
        "name": "Service Invoicing",
        "before": "Only DIEN Materials were used.",
        "after": "YSER + SERV+ BUND Materials are used due to the standardized new RB concept."
      },
      {
        "name": "Billing of Costs (Cost Charging)",
        "before": "Without SD process but with FI-Billing.",
        "after": "Use of standardized RB concept for DIEN part-numbers. SD process implemented."
